targets.expr:
histogram_quantile(0.95,
  sum by (le) (rate(backend_api_request_duration_seconds_bucket{namespace="backend-api", exported_endpoint!~"/health|/ready|/metrics"}[5m]))
)

histogram_quantile(0.95,
  sum by (le) (rate(ml_api_request_duration_seconds_bucket{namespace="ml-api", exported_endpoint!~"/health|/ready|/metrics"}[5m]))
)

count(
  ALERTS{alertname!="InfoInhibitor", namespace=~"backend-api|ml-api|postgres", alertstate="firing", severity="critical"}
  or
  ALERTS{alertname!="InfoInhibitor", namespace="", service=~"backend-api|ml-api|postgres", alertstate="firing", severity="critical"}
) or vector(0)

count(
  ALERTS{alertname!="InfoInhibitor", namespace=~"backend-api|ml-api|postgres", alertstate="firing", severity="warning"}
  or
  ALERTS{alertname!="InfoInhibitor", namespace="", service=~"backend-api|ml-api|postgres", alertstate="firing", severity="warning"}
) or vector(0)

vector(0) unless on() (
  max by (app, alertname, severity) (
      label_replace(
        ALERTS{alertname!="InfoInhibitor", namespace=~"backend-api|ml-api|postgres", alertstate="pending"} or ALERTS{alertname!="InfoInhibitor", namespace=~"backend-api|ml-api|postgres", alertstate="firing"} * 2,
        "app", "$1", "namespace", "(.+)"
      )
    or
      label_replace(
        ALERTS{alertname!="InfoInhibitor", namespace="", service=~"backend-api|ml-api|postgres", alertstate="pending"} or ALERTS{alertname!="InfoInhibitor", namespace="", service=~"backend-api|ml-api|postgres", alertstate="firing"} * 2,
        "app", "$1", "service", "(.+)"
      )
  )
)

sum by (status) (
  increase(backend_api_db_queries_total{namespace="backend-api", job="backend-api", container="backend-api"}[$__rate_interval])
)

max by (state) (
  pg_stat_activity_max_tx_duration{namespace="postgres", datname="voize", state=~"active|idle in transaction"}
)

vector(0) unless on() (
  max by (namespace, pod) (
      (kube_pod_container_status_ready{namespace=~"backend-api|ml-api|postgres"} == bool 0) == 1
        unless on (namespace, pod) (kube_pod_status_phase{namespace=~"backend-api|ml-api|postgres", phase="Succeeded"} == 1)
        unless on (namespace, pod) kube_pod_deletion_timestamp{namespace=~"backend-api|ml-api|postgres"}
        unless on (namespace, pod) (time() - kube_pod_start_time{namespace=~"backend-api|ml-api|postgres"} < 60)
    or
      (increase(kube_pod_container_status_restarts_total{namespace=~"backend-api|ml-api|postgres"}[$__rate_interval]) > bool 0) == 1
  )
)

vector(0) unless on() (
  max by (namespace, pod) (
    (kube_pod_status_phase{namespace=~"backend-api|ml-api|postgres", phase="Pending"} == 1)
    and on (namespace, pod) (time() - kube_pod_created{namespace=~"backend-api|ml-api|postgres"} > 60)
  )
)

sum by (namespace, workload) (
  node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace=~"backend-api|ml-api|postgres"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

sum by (namespace, workload) (
  node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace=~"backend-api|ml-api|postgres"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)
/
sum by (namespace, workload) (
  kube_pod_container_resource_requests{resource="cpu", namespace=~"backend-api|ml-api|postgres"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

sum by (namespace, workload) (
  container_memory_working_set_bytes{container!="", image!="", namespace=~"backend-api|ml-api|postgres"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

max by (namespace, workload) (
  sum by (namespace, pod, container) (
    container_memory_working_set_bytes{container!="", image!="", namespace=~"backend-api|ml-api|postgres"}
  )
  / on (namespace, pod, container)
  kube_pod_container_resource_limits{resource="memory"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

topk(10,
  sum by (namespace, pod) (
    container_memory_working_set_bytes{container!="", image!="", namespace=~"backend-api|ml-api|postgres"}
  )
)

topk(10,
  sum by (namespace, pod) (
    node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace=~"backend-api|ml-api|postgres"}
  )
)

topk(10,
  sum by (namespace, pod) (
    rate(container_cpu_cfs_throttled_periods_total{container!="", namespace=~"backend-api|ml-api|postgres"}[$__rate_interval])
  )
  /
  sum by (namespace, pod) (
    rate(container_cpu_cfs_periods_total{container!="", namespace=~"backend-api|ml-api|postgres"}[$__rate_interval])
  )
)
